    $mod = 1000000007;

    // Simulate the binary search to determine which positions must be < x and which must be > x
    // The binary search algorithm:
    // l = 0, r = n - 1
    // while l <= r:
    //   m = (l + r) / 2 (integer division)
    //   if a[m] == x: return true
    //   if a[m] < x: l = m + 1
    //   else: r = m - 1
    // return false

    // We need to find all permutations where x is at position $pos and the binary search finds x.
    // This means that during the binary search, when we reach position $pos$, we must have a[pos] == x.
    // For the binary search to reach position $pos$, all previous comparisons must lead us there.

    // Let's simulate the binary search path and determine constraints on other positions.
    // We'll track which positions are visited and what constraints they impose.

    $l = 0;
    $r = $n - 1;
    $visited = array(); // positions that are checked before reaching $pos

    while (true) {
        $m = intdiv($l + $r, 2);

        if ($m == $pos) {
            // We've reached the position where x is. The binary search will find x here.
            break;
        }

        // Record that position $m is visited before $pos
        $visited[$m] = true;

        // Now, for the binary search to continue towards $pos$, we need to determine
        // whether a[m] < x or a[m] > x based on where $pos$ is relative to $m$.
        if ($pos > $m) {
            // We need to go right, so a[m] < x
            $l = $m + 1;
        } else {
            // We need to go left, so a[m] > x
            $r = $m - 1;
        }
    }

    // Now we have a set of positions that are visited before $pos$.
    // For each such position, we know whether it must be < x or > x.

    $lessThanX = 0;
    $greaterThanX = 0;

    $l = 0;
    $r = $n - 1;
    while (true) {
        $m = intdiv($l + $r, 2);

        if ($m == $pos) {
            break;
        }

        if ($pos > $m) {
            // a[m] must be < x
            $lessThanX++;
            $l = $m + 1;
        } else {
            // a[m] must be > x
            $greaterThanX++;
            $r = $m - 1;
        }
    }

    // The number of elements less than x is (x - 1)
    // The number of elements greater than x is (n - x)

    // We need to place:
    // - $lessThanX elements from the (x-1) elements that are < x into the positions that require < x
    // - $greaterThanX elements from the (n-x) elements that are > x into the positions that require > x
    // - The remaining positions (n - 1 - $lessThanX - $greaterThanX) can be filled with any of the remaining elements

    $totalOtherPositions = $n - 1 - $lessThanX - $greaterThanX;

    // Check if it's possible
    if ($lessThanX > $x - 1 || $greaterThanX > $n - $x) {
        echo 0;
        return;
    }

    // We need to:
    // 1. Choose $lessThanX elements from the (x-1) elements < x: C(x-1, lessThanX)
    // 2. Arrange them in the $lessThanX positions: lessThanX!
    // 3. Choose $greaterThanX elements from the (n-x) elements > x: C(n-x, greaterThanX)
    // 4. Arrange them in the $greaterThanX positions: greaterThanX!
    // 5. The remaining (totalOtherPositions) positions get the remaining elements: totalOtherPositions!

    // So the total count is:
    // C(x-1, lessThanX) * lessThanX! * C(n-x, greaterThanX) * greaterThanX! * totalOtherPositions!
    // = P(x-1, lessThanX) * P(n-x, greaterThanX) * totalOtherPositions!
    // where P(n, k) = n! / (n-k)!

    // Let's compute factorials up to n
    $fact = array();
    $fact[0] = 1;
    for ($i = 1; $i <= $n; $i++) {
        $fact[$i] = ($fact[$i-1] * $i) % $mod;
    }

    // P(n, k) = fact[n] / fact[n-k] mod mod
    // We need modular inverse for division

    function modPow($base, $exp, $mod) {
        $result = 1;
        $base = $base % $mod;
        while ($exp > 0) {
            if ($exp % 2 == 1) {
                $result = ($result * $base) % $mod;
            }
            $exp = intdiv($exp, 2);
            $base = ($base * $base) % $mod;
        }
        return $result;
    }

    function modInv($a, $mod) {
        return modPow($a, $mod - 2, $mod);
    }

    // P(x-1, lessThanX) = fact[x-1] / fact[x-1-lessThanX]
    $p1 = ($fact[$x - 1] * modInv($fact[$x - 1 - $lessThanX], $mod)) % $mod;

    // P(n-x, greaterThanX) = fact[n-x] / fact[n-x-greaterThanX]
    $p2 = ($fact[$n - $x] * modInv($fact[$n - $x - $greaterThanX], $mod)) % $mod;

    // totalOtherPositions!
    $p3 = $fact[$totalOtherPositions];

    $result = ($p1 * $p2) % $mod;
    $result = ($result * $p3) % $mod;

    echo $result;
}

