$mod = 1000000007;

function solve() {
    global $mod;

    // Read input
    $line = trim(fgets(STDIN));
    $parts = explode(' ', $line);
    $n = (int)$parts[0];
    $x = (int)$parts[1];
    $pos = (int)$parts[2];

    // Precompute factorials
    $fact = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; $i++) {
        $fact[$i] = ($fact[$i - 1] * $i) % $mod;
    }

    // Precompute inverse factorials
    $invFact = array_fill(0, $n + 1, 1);
    $invFact[$n] = pow($fact[$n], $mod - 2, $mod);
    for ($i = $n - 1; $i >= 0; $i--) {
        $invFact[$i] = ($invFact[$i + 1] * ($i + 1)) % $mod;
    }

    // nCr function
    function nCr($n, $r, $fact, $invFact, $mod) {
        if ($r < 0 || $r > $n) return 0;
        return ($fact[$n] * $invFact[$r] % $mod * $invFact[$n - $r]) % $mod;
    }

    // Simulate binary search to determine which positions are compared
    // and what constraints they impose
    $lo = 0;
    $hi = $n - 1;
    $compared = [];
    $found = false;

    while ($lo <= $hi) {
        $mid = intdiv($lo + $hi, 2);
        $compared[] = $mid;

        if ($mid === $pos) {
            $found = true;
            break;
        }

        // We need to determine whether a[mid] < x or a[mid] > x
        // For the algorithm to continue correctly and eventually find x at pos,
        // the comparisons must lead us to pos.

        // If mid < pos, we need a[mid] < x so that lo = mid + 1
        // If mid > pos, we need a[mid] > x so that hi = mid - 1

        if ($mid < $pos) {
            // Need a[mid] < x
            $lo = $mid + 1;
        } else {
            // Need a[mid] > x
            $hi = $mid - 1;
        }
    }

    if (!$found) {
        echo 0 . "\n";
        return;
    }

    // Now we have a set of compared positions (excluding pos itself which is the last one)
    // For each compared position mid (not equal to pos):
    //   if mid < pos: a[mid] must be < x
    //   if mid > pos: a[mid] must be > x

    // Count how many positions need values < x and how many need values > x
    $needLess = 0;
    $needGreater = 0;
    for ($i = 0; $i < count($compared); $i++) {
        if ($compared[$i] === $pos) continue;
        if ($compared[$i] < $pos) {
            $needLess++;
        } else {
            $needGreater++;
        }
    }

    // Available numbers less than x: x - 1
    // Available numbers greater than x: n - x

    if ($needLess > $x - 1 || $needGreater > $n - $x) {
        echo 0 . "\n";
        return;
    }

    // We need to assign:
    // - $needLess distinct numbers from {1, ..., x-1} to the positions that need < x
    // - $needGreater distinct numbers from {x+1, ..., n} to the positions that need > x
    // - The remaining positions (n - 1 - needLess - needGreater) can be filled with any of the remaining numbers

    // Number of ways:
    // Choose and arrange needLess numbers from (x-1) available: P(x-1, needLess) = (x-1)! / (x-1-needLess)!
    // Choose and arrange needGreater numbers from (n-x) available: P(n-x, needGreater) = (n-x)! / (n-x-needGreater)!
    // The remaining (n - 1 - needLess - needGreater) positions get the remaining (n - 1 - needLess - needGreater) numbers in any order: (n - 1 - needLess - needGreater)!

    // Total = P(x-1, needLess) * P(n-x, needGreater) * (n - 1 - needLess - needGreater)!

    $remaining = $n - 1 - $needLess - $needGreater;

    $waysLess = 1;
    for ($i = 0; $i < $needLess; $i++) {
        $waysLess = ($waysLess * ($x - 1 - $i)) % $mod;
    }

    $waysGreater = 1;
    for ($i = 0; $i < $needGreater; $i++) {
        $waysGreater = ($waysGreater * ($n - $x - $i)) % $mod;
    }

    $result = ($waysLess * $waysGreater % $mod * $fact[$remaining]) % $mod;

    echo $result . "\n";
}

solve();
