    // 2. Choose which gt_count values from {x+1..n} go to gt_positions: P(n-x, gt_count)
    // 3. The remaining positions (n - 1 - lt_count - gt_count) get the remaining values
    //    Remaining values: (x-1 - lt_count) + (n-x - gt_count) = n - 1 - lt_count - gt_count
    //    Number of ways = (n - 1 - lt_count - gt_count)!

    $remaining = $n - 1 - $lt_count - $gt_count;

    // P(x-1, lt_count) = fact[x-1] / fact[x-1-lt_count]
    // P(n-x, gt_count) = fact[n-x] / fact[n-x-gt_count]

    $ways_lt = ($x - 1 - $lt_count >= 0) ? ($fact[$x - 1] * $invfact[$x - 1 - $lt_count] % $MOD) : 0;
    $ways_gt = ($n - $x - $gt_count >= 0) ? ($fact[$n - $x] * $invfact[$n - $x - $gt_count] % $MOD) : 0;
    $ways_rest = $fact[$remaining];

    $result = ($ways_lt * $ways_gt) % $MOD;
    $result = ($result * $ways_rest) % $MOD;

    echo $result;
}

solve();
